'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { ArrowRight, ChevronLeft, X } from 'lucide-react';
import { OnboardingProgress } from './OnboardingProgress';
import { StylePreference } from '@/lib/types/user-profile-types';
import useEmblaCarousel from 'embla-carousel-react';
import fashionStylesData from '@/lib/data/fashion-styles.json';

interface OnboardingStyleProps {
  onNext: (styles: StylePreference[]) => void;
  onBack: () => void;
}

// Import fashion styles from single source of truth
const styleOptions = fashionStylesData as StylePreference[];

export function OnboardingStyle({ onNext, onBack }: OnboardingStyleProps) {
  const [selectedStyles, setSelectedStyles] = useState<StylePreference[]>([]);
  const [failedImages, setFailedImages] = useState<Set<string>>(new Set());
  const [emblaRef] = useEmblaCarousel({
    align: 'start',
    containScroll: 'trimSnaps',
  });

  const handleImageError = (styleId: string) => {
    setFailedImages((prev) => new Set(prev).add(styleId));
  };

  const toggleStyle = (style: StylePreference) => {
    setSelectedStyles((prev) => {
      const isSelected = prev.some((s) => s.id === style.id);
      if (isSelected) {
        return prev.filter((s) => s.id !== style.id);
      } else {
        return [...prev, style];
      }
    });
  };

  const removeStyle = (styleId: string) => {
    setSelectedStyles((prev) => prev.filter((s) => s.id !== styleId));
  };

  const handleNext = () => {
    if (selectedStyles.length > 0) {
      onNext(selectedStyles);
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-[var(--onboarding-bg)]">
      {/* Back Button */}
      <div className="p-4">
        <Button
          variant="ghost"
          onClick={onBack}
          className="text-gray-600 hover:text-gray-900"
        >
          <ChevronLeft className="w-5 h-5" />
        </Button>
      </div>

      {/* Progress */}
      <OnboardingProgress currentStep={5} totalSteps={7} />

      {/* Content */}
      <div className="flex-1 flex flex-col p-6">
        <div className="max-w-4xl w-full mx-auto space-y-6">
          {/* Heading - Left Aligned */}
          <div className="text-left space-y-1">
            <h1 className="text-3xl font-bold text-[var(--onboarding-primary)]">
              What&apos;s your style?
            </h1>
            <p className="text-base text-gray-900">
              Choose style that sparks you
            </p>
          </div>

          {/* Selected Styles Thumbnails - Below Header, Left Aligned */}
          {selectedStyles.length > 0 && (
            <div className="flex gap-3 overflow-x-auto pb-2">
              {selectedStyles.map((style) => (
                <div
                  key={style.id}
                  className="relative flex-shrink-0 w-[60px] h-[80px] rounded-lg overflow-hidden border-2 border-[var(--onboarding-primary)]"
                >
                  <img
                    src={style.imageUrl || '/images/styles/Group 40.png'}
                    alt={`${style.name} style`}
                    className="w-full h-full object-cover"
                  />
                  <button
                    onClick={() => removeStyle(style.id)}
                    className="absolute top-1 right-1 w-5 h-5 bg-[var(--onboarding-primary)] rounded-full flex items-center justify-center shadow-sm"
                  >
                    <X className="w-3 h-3 text-white" />
                  </button>
                </div>
              ))}
            </div>
          )}

          {/* Carousel */}
          <div className="overflow-hidden max-w-md mx-auto md:max-w-none" ref={emblaRef}>
            <div className="flex gap-4 px-4">
              {styleOptions.map((style) => {
                const isSelected = selectedStyles.some((s) => s.id === style.id);
                return (
                  <div
                    key={style.id}
                    className="flex-[0_0_240px] min-w-0"
                  >
                    <button
                      onClick={() => toggleStyle(style)}
                      className={`
                        w-full rounded-2xl p-4 flex flex-col items-center
                        transition-all duration-300 bg-white
                        ${
                          isSelected
                            ? 'border-l-4 border-[var(--onboarding-primary)]'
                            : 'border-l-4 border-transparent'
                        }
                      `}
                    >
                      {/* Style Image - Cropped to hide text */}
                      <div className="w-full h-72 rounded-xl mb-3 overflow-hidden">
                        {style.imageUrl && !failedImages.has(style.id) ? (
                          <img
                            src={style.imageUrl}
                            alt={`${style.name} style`}
                            loading="lazy"
                            onError={() => handleImageError(style.id)}
                            className="w-full h-full object-cover object-center scale-110"
                          />
                        ) : (
                          <div className="w-full h-full bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">
                            <span className="text-4xl">👗</span>
                          </div>
                        )}
                      </div>

                      {/* Style Name - Red Text */}
                      <h3 className="text-lg font-bold text-[var(--onboarding-primary)] text-center">
                        {style.name} · {style.description}
                      </h3>

                      {/* Long Description - Gray Text */}
                      {style.longDescription && (
                        <p className="mt-2 text-sm text-gray-500 text-center line-clamp-3">
                          {style.longDescription}
                        </p>
                      )}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Next Button - Bottom Center */}
          <div className="flex justify-center pt-4">
            <Button
              onClick={handleNext}
              disabled={selectedStyles.length === 0}
              className="w-14 h-14 rounded-full bg-[var(--onboarding-primary)] hover:bg-[var(--onboarding-primary-hover)] text-white disabled:bg-gray-300 disabled:cursor-not-allowed"
            >
              <ArrowRight className="w-6 h-6" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

